@extends('layouts.app') @section('title','Ajukan Surat') @section('content')<div class="container py-4"><div class="row justify-content-center"><div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h3>Ajukan Surat</h3><p class="text-secondary">Pilih jenis surat. Persyaratan dan alurnya dibuat oleh Admin.</p><form method="POST" enctype="multipart/form-data" action="{{ route('surat.store') }}">@csrf<div class="mb-3"><label class="form-label">Jenis Surat</label><select class="form-select" name="letter_type_id" id="type" onchange="renderReq()" required><option value="">Pilih</option>@foreach($types as $t)<option value="{{ $t->id }}">{{ $t->title }}</option>@endforeach</select></div><div class="mb-3"><label class="form-label">Laboratorium terkait (opsional)</label><select class="form-select" name="laboratory_id"><option value="">Tidak spesifik</option>@foreach($laboratories as $l)<option value="{{ $l->id }}">{{ $l->name }}</option>@endforeach</select></div><div class="mb-3"><label class="form-label">Subjek</label><input class="form-control" name="subject" required></div><div class="mb-3"><label class="form-label">Catatan</label><textarea class="form-control" name="notes"></textarea></div><div id="reqbox"></div><button class="btn btn-primary mt-3">Kirim Surat</button></form></div></div></div></div></div>@endsection @push('scripts')<script>const types=@json($types->map(fn($t)=>['id'=>$t->id,'reqs'=>$t->requirements->map(fn($r)=>['id'=>$r->id,'title'=>$r->title,'required'=>$r->is_required]),'steps'=>$t->workflowSteps->map(fn($s)=>$s->label)]));function renderReq(){let t=types.find(x=>x.id==document.getElementById('type').value),b=document.getElementById('reqbox');b.innerHTML='';if(!t)return;b.innerHTML='<hr><h5>Persyaratan</h5>'+t.reqs.map(r=>`<div class="mb-3"><label class="form-label">${r.title}</label><input type="file" class="form-control" name="letter_req_${r.id}" ${r.required?'required':''}></div>`).join('')+'<h6>Alur</h6><div class="s